args:
d=$(echo "${XDG_CURRENT_DESKTOP:-}" | tr '[:upper:]' '[:lower:]'); echo "DESKTOP: $d ($XDG_SESSION_TYPE)"
case "$d" in
 *cinnamon*) cinnamon-dbus-command RestartCinnamon 1 2>/dev/null || (setsid -f cinnamon --replace >/dev/null 2>&1) ;;
 *kde*) systemctl --user restart plasma-plasmashell 2>/dev/null || (kquitapp6 plasmashell 2>/dev/null || kquitapp5 plasmashell; setsid -f plasmashell >/dev/null 2>&1) ;;
 *xfce*) xfce4-panel -r; (setsid -f xfdesktop --replace >/dev/null 2>&1) ;;
 *mate*) setsid -f mate-panel --replace >/dev/null 2>&1 ;;
 *gnome*|*unity*) if [ "$XDG_SESSION_TYPE" = x11 ]; then busctl --user call org.gnome.Shell /org/gnome/Shell org.gnome.Shell Eval s 'Meta.restart("Restarting…")' >/dev/null 2>&1 || echo GNOME_WAYLAND; else echo GNOME_WAYLAND; fi ;;
 *) echo UNKNOWN_DESKTOP ;;
esac
